  if (!onlineUsed()) {
    queueMicrotask(() => setAuthProbed(true)); // pure-local browser: no probe, no wait
    return;
  }
  void currentUser().then(
    (user) => { setOnlineUser(user); if (!user) setBrowsingLocal(false); setAuthProbed(true); },
    () => setAuthProbed(true) // probe failed (offline): stay logged-out, show the gate
