  return <AccountProfileSelect
    user={onlineUser}
    onPlay={(profile) => setScreen({ name: "online-worlds", profile })}
    onPlayLocally={() => { setBrowsingLocal(true); setScreen({ name: "profile-select" }); }}
    onSignedOut={() => { setOnlineUser(null); setScreen({ name: "welcome" }); }}
  />;
}
if (screen.name === "auth")
