import { afterAll, describe, expect, spyOn, test } from "bun:test";
import { db } from "./index";

// db() memoizes its instance, so order matters here: the production throw is
// asserted first (nothing gets memoized), then the dev fallback (which creates
// the singleton this file closes on exit — an unclosed PGlite leaks past the
// test run and turns the suite's exit code into 99).
const savedUrl = process.env.DATABASE_URL;
const savedNodeEnv = process.env.NODE_ENV;

afterAll(async () => {
  if (savedUrl === undefined) delete process.env.DATABASE_URL;
  else process.env.DATABASE_URL = savedUrl;
  process.env.NODE_ENV = savedNodeEnv;
  const client = (db() as unknown as { $client: { close(): Promise<void> } }).$client;
  await client.close();
});

describe("db() without DATABASE_URL", () => {
  test("production keeps the hard error", () => {
    delete process.env.DATABASE_URL;
    process.env.NODE_ENV = "production";
    expect(() => db()).toThrow(/DATABASE_URL is not set/);
  });

  test("dev falls back to in-memory PGlite and warns once", () => {
    delete process.env.DATABASE_URL;
    process.env.NODE_ENV = "test";
    const warn = spyOn(console, "warn").mockImplementation(() => {});
    try {
      const first = db();
      expect(first).toBeTruthy();
      expect(warn).toHaveBeenCalledTimes(1);
      expect(warn.mock.calls[0][0]).toContain("in-memory PGlite");
      // The memoized instance means no second warning (or second database).
      expect(db()).toBe(first);
      expect(warn).toHaveBeenCalledTimes(1);
    } finally {
      warn.mockRestore();
    }
  });
});

