3	import { useCallback, useEffect, useRef, useState } from "react";
4	import MinecraftGame from "@/components/MinecraftGame";
5	import AccountProfileSelect from "@/components/menu/AccountProfileSelect";
6	import OnlineWorldSelect from "@/components/menu/OnlineWorldSelect";
7	import ProfileSelect from "@/components/menu/ProfileSelect";
8	import WorldSelect from "@/components/menu/WorldSelect";
9	import { currentUser, onlineUsed, type OnlineUser } from "@/lib/auth/client";
10	import { migrateLegacySave } from "@/lib/game/legacyMigration";
11	import { DEFAULT_SKIN_ID, isSkinId } from "@/lib/game/playerSkins";
12	import { getProfile, setActiveProfile, type Profile } from "@/lib/game/profiles";
13	import { createWorld, deleteWorld, getWorld, touchWorld, worldSaveKey, type WorldMeta } from "@/lib/game/worlds";
14	import { writeSave } from "@/lib/game/save";
15	import { pullCloudSaveIfNewer } from "@/lib/game/cloudSaves";
16	import { deleteOnlineWorld, requestJoinTicket, type OnlineWorld } from "@/lib/online/onlineClient";
17	import type { OnlineProfile } from "@/lib/online/profilesClient";
18	import { connectNetworkSession, type NetworkSession } from "@/lib/net/NetworkSession";
19	import { installUiTiles } from "@/lib/ui/chromeTiles";
20	
21	/**
22	 * Top-level menu shell. Owns the screen state machine (profile-select ->
23	 * world-select -> play) and boots the legacy migration once on mount. The play
24	 * screen mounts MinecraftGame keyed by world id + a reload nonce, so switching
25	 * worlds (or Load/Reset) remounts the subtree — the game effect's cleanup
26	 * disposes the old engine/renderer and a fresh mount boots the next world, with
27	 * no page reload.
28	 */
29	type Screen =
30	  | { name: "profile-select" }
31	  | { name: "world-select"; profileId: string }
32	  | { name: "online-worlds"; profile: OnlineProfile }
33	  | { name: "play"; profileId: string; worldId: string }
34	  // An account profile's singleplayer (sp-cloud) world: full local engine, no
35	  // game server — the save syncs to the account as a cloud blob.
36	  | { name: "play-cloud"; profile: OnlineProfile; world: OnlineWorld }
37	  // play-online carries the play-usable identity derived from the account
38	  // profile, plus that profile itself so "quit to worlds" returns to its list.
39	  | { name: "play-online"; profile: Profile; world: OnlineWorld; session: NetworkSession; onlineProfile: OnlineProfile };
40	
41	/** A play-usable Profile from a server-side account profile (skin sanitized). */
42	function profileFromOnline(profile: OnlineProfile): Profile {
43	  return { id: profile.id, name: profile.name, skinId: isSkinId(profile.skinId) ? profile.skinId : DEFAULT_SKIN_ID, createdAt: 0 };
44	}
45	
46	/**
47	 * An account singleplayer world's meta: the `cloud:` id keys this device's
48	 * localStorage save cache, and `cloudId` makes the game hook's autosave sync
49	 * push every save up to the account blob.
50	 */
51	function cloudWorldMeta(world: OnlineWorld, profileId: string): WorldMeta {
52	  return { ...onlineWorldMeta(world, profileId), id: `cloud:${world.id}`, cloudId: world.id };
53	}
54	
55	/** Online worlds mount the same game subtree; the meta is a projection of the server row. */
56	function onlineWorldMeta(world: OnlineWorld, profileId: string): WorldMeta {
57	  return {
58	    id: `online:${world.id}`,
59	    profileId,
60	    name: world.name,
61	    seed: world.seed,
62	    worldType: world.worldType as WorldMeta["worldType"],
63	    gameMode: world.gameMode as WorldMeta["gameMode"],
64	    difficulty: world.difficulty as WorldMeta["difficulty"],
65	    hardcore: world.hardcore,
66	    worldgenVersion: world.worldgenVersion,
67	    createdAt: 0,
68	    lastPlayedAt: 0
69	  };
70	}
71	
72	/**
73	 * Remembers the world being played for this tab so a reload resumes it instead
74	 * of dropping back to the menu. sessionStorage (not localStorage) so a brand-new
75	 * tab still cold-starts at profile-select.
76	 */
77	const SESSION_KEY = "monecraft_active_session";
78	
79	function readSessionPointer(): { profileId: string; worldId: string } | null {
80	  try {
81	    const raw = sessionStorage.getItem(SESSION_KEY);
82	    if (!raw) return null;
83	    const parsed = JSON.parse(raw) as { profileId?: unknown; worldId?: unknown };
84	    if (typeof parsed?.profileId === "string" && typeof parsed?.worldId === "string") {
85	      return { profileId: parsed.profileId, worldId: parsed.worldId };
86	    }
87	    return null;
88	  } catch {
89	    return null;
90	  }
91	}
92	
93	function writeSessionPointer(pointer: { profileId: string; worldId: string } | null): void {
94	  try {
95	    if (pointer) sessionStorage.setItem(SESSION_KEY, JSON.stringify(pointer));
96	    else sessionStorage.removeItem(SESSION_KEY);
97	  } catch {
98	    // No resume across reload if sessionStorage is unavailable — never fatal.
99	  }
100	}
101	
102	export default function GameShell() {
103	  const [ready, setReady] = useState(false);
104	  const [screen, setScreen] = useState<Screen>({ name: "profile-select" });
105	  const [reloadNonce, setReloadNonce] = useState(0);
106	  const [connecting, setConnecting] = useState<string | null>(null);
107	  const [connectError, setConnectError] = useState<string | null>(null);
108	  // A join is in flight — guards against a double-click opening (and leaking) a
109	  // second socket. A ref, not `connecting`, so it's set synchronously.
110	  const joiningRef = useRef(false);
111	  // The signed-in account (its presence flips the menu into account mode).
112	  // Offline-first: never asked until this browser went online.
113	  const [onlineUser, setOnlineUser] = useState<OnlineUser | null>(null);
114	  // The "Play locally" door: a signed-in account browsing its local (browser)
115	  // profiles/worlds — where cloud-save sync lives — without signing out.
116	  const [browsingLocal, setBrowsingLocal] = useState(false);
117	  const refreshOnlineUser = useCallback(() => {
118	    if (onlineUsed())
119	      void currentUser().then((user) => {
120	        setOnlineUser(user);
121	        if (!user) setBrowsingLocal(false); // signed out: the door has no "back"
122	      });
123	  }, []);
124	
125	  /**
126	   * Open a world for play. A cloud-linked one (WorldMeta.cloudId) reconciles
127	   * first: pull the remote save if it advanced past this device's cursor, write
128	   * it to disk, and boot from disk like any other world — reusing the "Opening…"
129	   * gate. The caller owns the `joiningRef` guard (this helper does not), so the
130	   * materialize-then-open path can hold it across `createWorld` too.
131	   */
132	  const openWorld = async (profileId: string, worldId: string) => {
133	    const world = getWorld(worldId);
134	    touchWorld(worldId);
135	    writeSessionPointer({ profileId, worldId });
136	    if (world?.cloudId) {
137	      setConnecting(world.name);
138	      try {
139	        const decision = await pullCloudSaveIfNewer(world.cloudId);
140	        if (decision.adopt) writeSave(worldSaveKey(worldId), decision.save);
141	      } catch {
142	        // Offline or a bad blob → fall through and play the local copy.
143	      } finally {
144	        setConnecting(null);
145	      }
146	    }
147	    setScreen({ name: "play", profileId, worldId });
148	  };
149	
150	  const playLocal = async (profileId: string, worldId: string) => {
151	    if (joiningRef.current) return;
152	    joiningRef.current = true;
153	    try {
154	      await openWorld(profileId, worldId);
155	    } finally {
156	      joiningRef.current = false;
157	    }
158	  };
159	
160	  /**
161	   * Open an account singleplayer world: reconcile this device's save cache
162	   * with the cloud blob (adopt the remote only when it advanced past our
163	   * cursor), then boot the full local engine — no game server involved.
164	   * Unlike local worlds there is no manifest entry and no session-resume
165	   * pointer; a reload lands back on the menu (like play-online).
166	   */
167	  const playCloud = async (profile: OnlineProfile, world: OnlineWorld) => {
168	    if (joiningRef.current) return;
169	    joiningRef.current = true;
170	    setConnecting(world.name);
171	    try {
172	      const decision = await pullCloudSaveIfNewer(world.id);
173	      if (decision.adopt) writeSave(worldSaveKey(`cloud:${world.id}`), decision.save);
174	    } catch {
175	      // Offline or a bad blob → play this device's cache (or a fresh world).
176	    } finally {
177	      setConnecting(null);
178	      joiningRef.current = false;
179	    }
180	    setScreen({ name: "play-cloud", profile, world });
181	  };
182	
183	  /** Materialize a cloud save as a local world (linked by cloudId), then open it — the pull-on-open fills it in. */
184	  const downloadCloud = async (profileId: string, world: OnlineWorld) => {
185	    // Guard BEFORE createWorld so a fast double-click can't persist two local
186	    // worlds sharing the same cloudId (the second open would just be dropped).
187	    if (joiningRef.current) return;
188	    joiningRef.current = true;
189	    try {
190	      const local = createWorld(profileId, world.name, String(world.seed), {
191	        worldType: world.worldType as WorldMeta["worldType"],
192	        gameMode: world.gameMode as WorldMeta["gameMode"],
193	        difficulty: world.difficulty as WorldMeta["difficulty"],
194	        hardcore: world.hardcore,
195	        worldgenVersion: world.worldgenVersion,
196	        cloudId: world.id
197	      });
198	      await openWorld(profileId, local.id);
199	    } finally {
200	      joiningRef.current = false;
201	    }
202	  };
203	
204	  /** Account profile → ticket → socket → replica sync → play. The profile's id
205	   *  rides the ticket so the roster shows that profile's name and skin. */
206	  const playOnline = async (profile: Profile, world: OnlineWorld, onlineProfile: OnlineProfile) => {
207	    if (joiningRef.current) return; // a join is already in flight
208	    joiningRef.current = true;
209	    setConnectError(null);
210	    setConnecting(world.name);
211	    const ticketProfileId = onlineProfile.id;
212	    try {
213	      // No sign-in pre-check: this is only reachable from account mode, and an
214	      // expired session just fails the ticket mint into the dialog below.
215	      const grant = await requestJoinTicket(world.id, ticketProfileId);
216	      if (!grant) throw new Error("could not get a join ticket — are you still signed in, and is the game server configured?");
217	      // The reconnect ladder mints a fresh short-lived ticket each retry — the
218	      // 60 s TTL means a stale one is useless a minute after a drop.
219	      const session = await connectNetworkSession(grant.gameServerUrl, grant.ticket, undefined, {
220	        reconnect: async () => {
221	          const next = await requestJoinTicket(world.id, ticketProfileId);
222	          return next ? { url: next.gameServerUrl, ticket: next.ticket } : null;
223	        }
224	      });
225	      setScreen({ name: "play-online", profile, world, session, onlineProfile });
226	    } catch (error) {
227	      setConnectError(error instanceof Error ? error.message : "connection failed");
228	    } finally {
229	      setConnecting(null);
230	      joiningRef.current = false;
231	    }
232	  };
233	
234	  useEffect(() => {
235	    installUiTiles(); // the menu chrome shares the in-game noise tiles
236	    migrateLegacySave();
237	    // Resume the tab's world if one was being played and still exists.
238	    const pointer = readSessionPointer();
239	    const resume: Screen | null =
240	      pointer && getProfile(pointer.profileId) && getWorld(pointer.worldId) ? { name: "play", profileId: pointer.profileId, worldId: pointer.worldId } : null;
241	    // Microtask hop keeps this off the synchronous effect path (cascading-render lint).
242	    queueMicrotask(() => {
243	      if (resume) {
244	        setScreen(resume);
245	        // A resumed local world means the player came through the local menus —
246	        // quitting should walk back out through them, even for a signed-in
247	        // account, not jump abruptly to the account home.
248	        setBrowsingLocal(true);
249	      }
250	      setReady(true);
251	    });
252	  }, []);
253	
254	  // Discover an existing account session so a signed-in reload lands in account
255	  // mode (offline-first: refreshOnlineUser no-ops until this browser went online).
256	  useEffect(() => refreshOnlineUser(), [refreshOnlineUser]);
257	
258	  // The "Opening…" gate and join-failure dialog, shared by both world lists.
259	  const netModals = (
260	    <>
261	      {connecting && (
262	        <div className="net-modal" role="status">
263	          <div className="net-modal-box">Opening “{connecting}”…</div>
264	        </div>
265	      )}
266	      {connectError && (
267	        <div className="net-modal" role="alertdialog" aria-label="Connection failed">
268	          <div className="net-modal-box">
269	            <p>Couldn&apos;t join: {connectError}</p>
270	            <button type="button" className="mc-button" onClick={() => setConnectError(null)}>
271	              OK
272	            </button>
273	          </div>
274	        </div>
275	      )}
276	    </>
277	  );
278	
279	  // localStorage is read below; hold the neutral frame until we're client-side.
280	  if (!ready) return <div className="menu-screen" />;
281	
282	  if (screen.name === "play") {
283	    const profile = getProfile(screen.profileId);
284	    const world = getWorld(screen.worldId);
285	    // Both exist in normal flow; a cross-tab delete drops us back to a menu.
286	    if (profile && world) {
287	      return (
288	        <MinecraftGame
289	          key={`${world.id}:${reloadNonce}`}
290	          world={world}
291	          profile={profile}
292	          onQuitToWorlds={() => {
293	            writeSessionPointer(null);
294	            setScreen({ name: "world-select", profileId: profile.id });
295	          }}
296	          onDeleteWorld={() => {
297	            deleteWorld(world.id); // hardcore Game Over: erase the dead world and leave
298	            writeSessionPointer(null);
299	            setScreen({ name: "world-select", profileId: profile.id });
300	          }}
301	          onReloadWorld={() => setReloadNonce((nonce) => nonce + 1)}
302	        />
303	      );
304	    }
305	  }
306	
307	  if (screen.name === "play-cloud") {
308	    const backToWorlds: Screen = { name: "online-worlds", profile: screen.profile };
309	    return (
310	      <MinecraftGame
311	        key={`cloud:${screen.world.id}:${reloadNonce}`}
312	        world={cloudWorldMeta(screen.world, screen.profile.id)}
313	        profile={profileFromOnline(screen.profile)}
314	        onQuitToWorlds={() => setScreen(backToWorlds)}
315	        onDeleteWorld={() => {
316	          // Hardcore game-over: delete the cloud world (row + blob), then this
317	          // device's save cache — only after the server confirmed, so a failed
318	          // delete (offline) leaves a still-playable world in the list rather
319	          // than a hollow one that re-downloads its own game-over.
320	          void deleteOnlineWorld(screen.world.id).then((deleted) => {
321	            if (!deleted) return;
322	            try {
323	              localStorage.removeItem(worldSaveKey(`cloud:${screen.world.id}`));
324	            } catch {
325	              // Cache cleanup only — never fatal.
326	            }
327	          });
328	          setScreen(backToWorlds);
329	        }}
330	        onReloadWorld={() => setReloadNonce((nonce) => nonce + 1)}
331	      />
332	    );
333	  }
334	
335	  if (screen.name === "play-online") {
336	    // Quit returns to the account profile's online worlds.
337	    const backToWorlds: Screen = { name: "online-worlds", profile: screen.onlineProfile };
338	    return (
339	      <MinecraftGame
340	        key={`online:${screen.world.id}`}
341	        world={onlineWorldMeta(screen.world, screen.profile.id)}
342	        profile={screen.profile}
343	        online={screen.session}
344	        onQuitToWorlds={() => setScreen(backToWorlds)}
345	        onDeleteWorld={() => {
346	          // Hardcore game-over: actually delete the shared world on the server
347	          // (owner-gated; a member just leaves), then return to the list.
348	          screen.session.dispose();
349	          void deleteOnlineWorld(screen.world.id);
350	          setScreen(backToWorlds);
351	        }}
352	        onReloadWorld={() => setScreen(backToWorlds)}
353	      />
354	    );
355	  }
356	
357	  if (screen.name === "world-select") {
358	    const profile = getProfile(screen.profileId);
359	    if (profile) {
360	      return (
361	        <>
362	          <WorldSelect
363	            profile={profile}
364	            onPlay={(worldId) => void playLocal(profile.id, worldId)}
365	            onDownloadCloud={(world) => void downloadCloud(profile.id, world)}
366	            cloudEnabled={onlineUser !== null}
367	            onBack={() => setScreen({ name: "profile-select" })}
368	          />
369	          {netModals}
370	        </>
371	      );
372	    }
373	  }
374	
375	  if (screen.name === "online-worlds") {
376	    return (
377	      <>
378	        <OnlineWorldSelect
379	          profile={screen.profile}
380	          onPlayOnline={(world) => void playOnline(profileFromOnline(screen.profile), world, screen.profile)}
381	          onPlayCloud={(world) => void playCloud(screen.profile, world)}
382	          onBack={() => setScreen({ name: "profile-select" })}
383	        />
384	        {netModals}
385	      </>
386	    );
387	  }
388	
389	  // The profile-select screen is auth-aware: a signed-in account browses its
390	  // synced online profiles (unless it stepped through the "Play locally" door);
391	  // everyone else gets the local (browser) profiles.
392	  const accountMode = onlineUser !== null;
393	  if (accountMode && !browsingLocal) {
394	    return (
395	      <AccountProfileSelect
396	        user={onlineUser}
397	        onPlay={(profile) => setScreen({ name: "online-worlds", profile })}
398	        onPlayLocally={() => setBrowsingLocal(true)}
399	        onSignedOut={() => setOnlineUser(null)}
400	      />
401	    );
402	  }
403	
404	  return (
405	    <ProfileSelect
406	      onPlay={(profileId) => {
407	        setActiveProfile(profileId);
408	        setScreen({ name: "world-select", profileId });
409	      }}
410	      onAuthChange={refreshOnlineUser}
411	      onBackToAccount={accountMode ? () => setBrowsingLocal(false) : undefined}
412	    />
413	  );
414	}
