test("the create button is disabled once the profile cap is reached", async () => {
  fake.profiles = Array.from({ length: MAX_ONLINE_PROFILES }, (_, i) => ({ id: `p${i}`, name: `P${i}`, skinId: null, createdAt: `${i}` }));
